<?php
declare(strict_types=1);

namespace Erp\Modules\Invoicing;

use Erp\Core\Security\AccessDeniedException;
use Erp\Core\Security\Authorization;
use Erp\Core\Security\UserContext;
use InvalidArgumentException;
use PDO;
use Throwable;

final class InvoicingRepository
{
    private const ACCOUNT_TYPES = [
        'asset_receivable', 'asset_cash', 'asset_current', 'asset_non_current', 'asset_prepayments', 'asset_fixed',
        'liability_payable', 'liability_credit_card', 'liability_current', 'liability_non_current',
        'equity', 'equity_unaffected', 'equity_retained',
        'income', 'income_other', 'expense', 'expense_other', 'expense_depreciation', 'expense_direct_cost', 'off_balance',
    ];

    public function __construct(private readonly PDO $pdo) {}

    public function options(UserContext $user, Authorization $authorization, mixed $rawCompanyId): array
    {
        $companyId = $this->company($user, $authorization, $rawCompanyId);
        $accounts = $this->pdo->prepare('SELECT id,code,name,account_type,allow_reconciliation FROM accounting_accounts WHERE company_id=:company_id AND active=1 ORDER BY code,id');
        $accounts->execute(['company_id' => $companyId]);
        $journals = $this->pdo->prepare("SELECT id,code,name,journal_type FROM accounting_journals WHERE company_id=:company_id AND active=1 AND journal_type='sale' ORDER BY name,id");
        $journals->execute(['company_id' => $companyId]);
        $paymentJournals = $this->pdo->prepare("SELECT j.id,j.code,j.name,j.journal_type,j.default_account_id,a.code AS default_account_code,a.name AS default_account_name,j.outstanding_receipts_account_id,o.code AS outstanding_account_code,o.name AS outstanding_account_name,j.outstanding_payments_account_id,op.code AS outstanding_payments_account_code,op.name AS outstanding_payments_account_name FROM accounting_journals j JOIN accounting_accounts a ON a.id=j.default_account_id LEFT JOIN accounting_accounts o ON o.id=j.outstanding_receipts_account_id LEFT JOIN accounting_accounts op ON op.id=j.outstanding_payments_account_id WHERE j.company_id=:company_id AND j.active=1 AND j.journal_type IN ('bank','cash') AND a.active=1 AND ((o.id IS NOT NULL AND o.active=1) OR (op.id IS NOT NULL AND op.active=1)) ORDER BY j.name,j.id");
        $paymentJournals->execute(['company_id' => $companyId]);
        $customers = $this->pdo->prepare('SELECT id,name,email,company_id FROM contacts WHERE active=1 AND customer=1 AND (company_id IS NULL OR company_id=:company_id) ORDER BY name,id LIMIT 2000');
        $customers->execute(['company_id' => $companyId]);
        $invoiceContacts = $this->pdo->prepare('SELECT id,name,parent_contact_id,company_id FROM contacts WHERE active=1 AND (company_id IS NULL OR company_id=:company_id) ORDER BY name,id LIMIT 2000');
        $invoiceContacts->execute(['company_id' => $companyId]);
        $products = $this->pdo->prepare('SELECT p.id,p.name,p.product_type,p.uom_id,p.list_price,u.name AS uom_name,u.category_id FROM products p JOIN units_of_measure u ON u.id=p.uom_id WHERE p.company_id=:company_id AND p.active=1 AND p.sale_ok=1 ORDER BY p.name,p.id LIMIT 2000');
        $products->execute(['company_id' => $companyId]);
        $units = $this->pdo->prepare('SELECT u.id,u.name,u.abbreviation,u.category_id,u.factor_to_reference FROM units_of_measure u JOIN uom_categories c ON c.id=u.category_id WHERE u.active=1 AND c.active=1 AND (u.company_id IS NULL OR u.company_id=:unit_company) AND (c.company_id IS NULL OR c.company_id=:category_company) ORDER BY c.name,u.name,u.id');
        $units->execute(['unit_company'=>$companyId,'category_company'=>$companyId]);
        $taxes = $this->pdo->prepare('SELECT id,name,amount,price_included FROM sales_taxes WHERE active=1 AND (company_id IS NULL OR company_id=:company_id) ORDER BY name,id');
        $taxes->execute(['company_id' => $companyId]);
        $company = $this->pdo->prepare('SELECT c.currency_code,cur.decimal_places FROM companies c JOIN currencies cur ON cur.currency_code=c.currency_code WHERE c.id=:company_id AND c.active=1');
        $company->execute(['company_id' => $companyId]);
        $companyValues = $company->fetch();
        return ['company_id' => $companyId, 'currency_code' => $companyValues['currency_code'] ?? null,
            'decimal_places' => (int)($companyValues['decimal_places'] ?? 2), 'accounts' => $accounts->fetchAll(), 'journals' => $journals->fetchAll(), 'payment_journals' => $paymentJournals->fetchAll(), 'customers'=>$customers->fetchAll(), 'invoice_contacts'=>$invoiceContacts->fetchAll(), 'service_products'=>$products->fetchAll(), 'units'=>$units->fetchAll(), 'taxes'=>$taxes->fetchAll()];
    }

    public function search(UserContext $user, Authorization $authorization, array $filters): array
    {
        $companyId = $this->company($user, $authorization, $filters['company_id'] ?? null);
        $where = ['i.company_id=:company_id']; $params = ['company_id' => $companyId];
        $state = (string)($filters['state'] ?? 'all');
        if ($state !== 'all') {
            if (!in_array($state, ['draft','posted','cancelled'], true)) throw new InvalidArgumentException('Select a valid invoice state.');
            $where[] = 'i.state=:state'; $params['state'] = $state;
        }
        if (($filters['partner_contact_id'] ?? '') !== '') { $where[] = 'i.partner_contact_id=:partner'; $params['partner'] = $this->positiveId($filters['partner_contact_id'], 'Contact'); }
        $queryText = trim((string)($filters['q'] ?? ''));
        if ($queryText !== '') {
            if (mb_strlen($queryText) > 190) throw new InvalidArgumentException('Invoice search must be 190 characters or fewer.');
            $where[] = '(i.name LIKE :invoice_q OR c.name LIKE :customer_q OR so.name LIKE :order_q)';
            $like = '%' . str_replace(['!','%','_'], ['!!','!%','!_'], $queryText) . '%';
            $params += ['invoice_q'=>$like,'customer_q'=>$like,'order_q'=>$like];
        }
        $clause = implode(' AND ', $where);
        $count = $this->pdo->prepare('SELECT COUNT(*) FROM customer_invoices i JOIN contacts c ON c.id=i.partner_contact_id LEFT JOIN sales_orders so ON so.id=i.sales_order_id WHERE ' . $clause);
        $count->execute($params); $total = (int)$count->fetchColumn();
        $limit = max(1,min(100,(int)($filters['limit'] ?? 50))); $offset = max(0,min(1000000,(int)($filters['offset'] ?? 0)));
        $list = $this->pdo->prepare('SELECT i.id,i.company_id,i.name,i.document_type,i.reversal_of_invoice_id,i.sales_order_id,so.name AS sales_order_name,i.partner_contact_id,c.name AS customer_name,i.currency_code,i.invoice_date,i.due_date,i.state,i.payment_state,i.amount_paid,i.amount_credited,i.amount_residual,i.untaxed_amount,i.tax_amount,i.total_amount,i.accounting_move_id,i.posted_at FROM customer_invoices i JOIN contacts c ON c.id=i.partner_contact_id LEFT JOIN sales_orders so ON so.id=i.sales_order_id WHERE ' . $clause . ' ORDER BY i.invoice_date DESC,i.id DESC LIMIT :limit OFFSET :offset');
        foreach ($params as $key=>$value) $list->bindValue(':' . $key, $value, is_int($value)?PDO::PARAM_INT:PDO::PARAM_STR);
        $list->bindValue(':limit',$limit,PDO::PARAM_INT); $list->bindValue(':offset',$offset,PDO::PARAM_INT); $list->execute();
        return ['records'=>$list->fetchAll(),'total'=>$total,'limit'=>$limit,'offset'=>$offset,'company_id'=>$companyId];
    }

    public function find(int $id, UserContext $user, Authorization $authorization): ?array
    {
        $query = $this->pdo->prepare('SELECT i.*,c.name AS customer_name,c.email AS customer_email,c.tax_id AS partner_tax_id,ic.name AS invoice_contact_name,ic.email AS invoice_contact_email,ic.phone AS invoice_contact_phone,so.name AS sales_order_name,source.name AS reversal_of_invoice_name,j.name AS journal_name,am.name AS accounting_move_name,am.state AS accounting_move_state,co.name AS print_company_name,co.legal_name AS print_company_legal_name,co.tax_id AS print_company_tax_id,co.email AS print_company_email,co.phone AS print_company_phone,co.website AS print_company_website,co.street AS print_company_street,co.street2 AS print_company_street2,co.city AS print_company_city,co.state AS print_company_state,co.postal_code AS print_company_postal_code,co.country_code AS print_company_country_code FROM customer_invoices i JOIN contacts c ON c.id=i.partner_contact_id LEFT JOIN contacts ic ON ic.id=i.invoice_contact_id LEFT JOIN sales_orders so ON so.id=i.sales_order_id LEFT JOIN customer_invoices source ON source.id=i.reversal_of_invoice_id AND source.company_id=i.company_id JOIN accounting_journals j ON j.id=i.journal_id JOIN companies co ON co.id=i.company_id LEFT JOIN accounting_moves am ON am.id=i.accounting_move_id WHERE i.id=:id LIMIT 1');
        $query->execute(['id'=>$id]); $invoice=$query->fetch();
        if (!$invoice || !$authorization->canAccessCompany((int)$invoice['company_id'])) return null;
        $canReadAccounting = $authorization->allowsForCompany('accounting.read', (int)$invoice['company_id']);
        if (!$canReadAccounting) {
            $invoice['accounting_move_name'] = null;
            $invoice['accounting_move_state'] = null;
        }
        $addressQuery=$this->pdo->prepare("SELECT name,street,street2,city,state,postal_code,country_code,phone,email FROM contact_addresses WHERE contact_id=:contact AND active=1 ORDER BY (address_type='invoice') DESC,is_default DESC,id LIMIT 1");
        $addressQuery->execute(['contact'=>$invoice['invoice_contact_id']??$invoice['partner_contact_id']]);$invoice['print_invoice_address']=$addressQuery->fetch()?:[];
        $lines = $this->pdo->prepare('SELECT il.*,p.name AS product_name,p.product_type,u.name AS uom_name,u.factor_to_reference AS uom_factor,product_uom.name AS product_uom_name,product_uom.factor_to_reference AS product_uom_factor,u.abbreviation,t.account_id AS tax_account_id,sol.invoice_policy FROM customer_invoice_lines il JOIN products p ON p.id=il.product_id JOIN units_of_measure u ON u.id=il.uom_id JOIN units_of_measure product_uom ON product_uom.id=p.uom_id LEFT JOIN sales_order_lines sol ON sol.id=il.sales_order_line_id LEFT JOIN sales_taxes t ON t.id=il.tax_id WHERE il.invoice_id=:id ORDER BY il.sequence,il.id');
        $lines->execute(['id'=>$id]); $invoice['lines']=$lines->fetchAll();
        if($invoice['document_type']==='invoice'){$credited=$this->pdo->prepare("SELECT cl.reversal_of_line_id,CAST(SUM(cl.quantity) AS DECIMAL(20,6)) AS quantity FROM customer_invoice_lines cl JOIN customer_invoices cn ON cn.id=cl.invoice_id WHERE cn.company_id=:company AND cn.document_type='credit_note' AND cn.reversal_of_invoice_id=:invoice AND cn.state='posted' GROUP BY cl.reversal_of_line_id");$credited->execute(['company'=>$invoice['company_id'],'invoice'=>$id]);$creditedByLine=[];foreach($credited->fetchAll() as $item)$creditedByLine[(int)$item['reversal_of_line_id']]=$item['quantity'];foreach($invoice['lines'] as &$line){$line['credited_quantity']=$creditedByLine[(int)$line['id']]??'0.000000';$line['creditable_quantity']=$this->maxZeroDecimal($this->subtractDecimal((string)$line['quantity'],(string)$line['credited_quantity']));}unset($line);}
        if ($canReadAccounting) {
            $moveLines = $this->pdo->prepare('SELECT ml.id,ml.sequence,ml.account_id,a.code AS account_code,a.name AS account_name,ml.contact_id,ml.label,ml.debit,ml.credit,ml.currency_code,ml.amount_currency FROM accounting_move_lines ml JOIN accounting_accounts a ON a.id=ml.account_id WHERE ml.move_id=:move_id ORDER BY ml.sequence,ml.id');
            $moveLines->execute(['move_id'=>$invoice['accounting_move_id'] ?? 0]); $invoice['journal_items']=$moveLines->fetchAll();
        } else $invoice['journal_items']=[];
        $payments = $this->pdo->prepare('SELECT p.id,p.name,p.journal_id,j.name AS journal_name,p.payment_date,p.amount,p.reference,p.state,p.accounting_move_id,am.name AS accounting_move_name,am.state AS accounting_move_state,p.paid_at,bsm.reference AS bank_reference,bsm.transaction_date AS bank_transaction_date,bsm.accounting_move_id AS bank_move_id,bank_am.name AS bank_move_name,bank_am.state AS bank_move_state FROM customer_payments p JOIN accounting_journals j ON j.id=p.journal_id LEFT JOIN accounting_moves am ON am.id=p.accounting_move_id LEFT JOIN bank_statement_matches bsm ON bsm.payment_id=p.id LEFT JOIN accounting_moves bank_am ON bank_am.id=bsm.accounting_move_id WHERE p.invoice_id=:invoice_id ORDER BY p.payment_date DESC,p.id DESC');
        $payments->execute(['invoice_id' => $id]); $invoice['payments']=$payments->fetchAll();
        if($invoice['document_type']==='invoice'){$creditNotes = $this->pdo->prepare("SELECT id,name,state,payment_state,invoice_date,total_amount,amount_paid,amount_applied,amount_residual,currency_code FROM customer_invoices WHERE company_id=:company AND document_type='credit_note' AND reversal_of_invoice_id=:invoice ORDER BY invoice_date DESC,id DESC");$creditNotes->execute(['company'=>$invoice['company_id'],'invoice'=>$id]);$invoice['credit_notes']=$creditNotes->fetchAll();}
        else $invoice['credit_notes']=[];
        $applications=$this->pdo->prepare('SELECT a.id,a.credit_note_id,credit.name AS credit_note_name,credit.reversal_of_invoice_id AS source_invoice_id,source.name AS source_invoice_name,a.customer_invoice_id AS target_invoice_id,target.name AS target_invoice_name,a.amount,a.applied_at FROM customer_credit_note_applications a JOIN customer_invoices credit ON credit.id=a.credit_note_id AND credit.company_id=a.company_id AND credit.document_type=\'credit_note\' JOIN customer_invoices source ON source.id=credit.reversal_of_invoice_id AND source.company_id=credit.company_id JOIN customer_invoices target ON target.id=a.customer_invoice_id AND target.company_id=a.company_id AND target.document_type=\'invoice\' WHERE a.company_id=:company AND (a.credit_note_id=:credit_note OR a.customer_invoice_id=:invoice OR credit.reversal_of_invoice_id=:source_invoice) ORDER BY a.applied_at DESC,a.id DESC');$applications->execute(['company'=>$invoice['company_id'],'credit_note'=>$id,'invoice'=>$id,'source_invoice'=>$id]);$invoice['credit_applications']=$applications->fetchAll();
        if($invoice['document_type']==='credit_note'){
            $returnLinks=$this->pdo->prepare('SELECT cra.credit_note_line_id,CAST(SUM(cra.quantity_product_uom) AS DECIMAL(20,6)) AS returned_product_quantity,sm.id AS return_move_id,sm.reference AS return_reference FROM customer_credit_note_return_allocations cra JOIN customer_invoice_lines cnl ON cnl.id=cra.credit_note_line_id JOIN customer_invoices cn ON cn.id=cnl.invoice_id AND cn.company_id=cra.company_id AND cn.document_type=\'credit_note\' JOIN stock_move_lines sml ON sml.id=cra.stock_move_line_id JOIN stock_moves sm ON sm.id=sml.move_id AND sm.company_id=cra.company_id WHERE cn.id=:credit_note AND cn.state IN (\'draft\',\'posted\') GROUP BY cra.credit_note_line_id,sm.id,sm.reference ORDER BY cra.credit_note_line_id,sm.id');
            $returnLinks->execute(['credit_note'=>$id]);$byCreditLine=[];
            foreach($returnLinks->fetchAll() as $link){$lineId=(int)$link['credit_note_line_id'];if(!isset($byCreditLine[$lineId]))$byCreditLine[$lineId]=['returned_product_quantity'=>'0.000000','return_move_ids'=>[],'return_references'=>[]];$byCreditLine[$lineId]['returned_product_quantity']=$this->addDecimal($byCreditLine[$lineId]['returned_product_quantity'],(string)$link['returned_product_quantity']);$moveId=(int)$link['return_move_id'];$byCreditLine[$lineId]['return_move_ids'][$moveId]=$moveId;if($link['return_reference']!==null)$byCreditLine[$lineId]['return_references'][$moveId]=(string)$link['return_reference'];}
            foreach($invoice['lines'] as &$line){$link=$byCreditLine[(int)$line['id']]??null;$productQty=(string)($link['returned_product_quantity']??'0.000000');$line['returned_quantity']=$this->calculate('CAST(ROUND(CAST(:quantity AS DECIMAL(20,6))*CAST(:product_factor AS DECIMAL(20,10))/CAST(:uom_factor AS DECIMAL(20,10)),6) AS DECIMAL(20,6))',['quantity'=>$productQty,'product_factor'=>$line['product_uom_factor'],'uom_factor'=>$line['uom_factor']]);$line['return_references']=$link?implode(', ',array_values($link['return_references'])):null;$line['return_move_ids']=$authorization->allowsForCompany('inventory.read',(int)$invoice['company_id'])&&$link?implode(',',array_values($link['return_move_ids'])):null;}unset($line);
        }
        if($invoice['document_type']==='invoice'){foreach($invoice['lines'] as &$line){$available=$line['product_type']==='goods'?$this->availableReturnedProductQuantity($line,(int)$invoice['company_id']):'0.000000';$line['available_return_quantity']=$this->calculate('CAST(ROUND(CAST(:quantity AS DECIMAL(20,6))*CAST(:product_factor AS DECIMAL(20,10))/CAST(:uom_factor AS DECIMAL(20,10)),6) AS DECIMAL(20,6))',['quantity'=>$available,'product_factor'=>$line['product_uom_factor'],'uom_factor'=>$line['uom_factor']]);}unset($line);}
        if($invoice['document_type']==='credit_note'){$refunds=$this->pdo->prepare('SELECT r.id,r.name,r.journal_id,j.name AS journal_name,r.payment_date,r.amount,r.reference,r.state,r.accounting_move_id,am.name AS accounting_move_name,am.state AS accounting_move_state,r.paid_at,m.reference AS bank_reference,m.transaction_date AS bank_transaction_date,m.accounting_move_id AS bank_move_id,bm.name AS bank_move_name,bm.state AS bank_move_state FROM customer_credit_note_refunds r JOIN accounting_journals j ON j.id=r.journal_id LEFT JOIN accounting_moves am ON am.id=r.accounting_move_id LEFT JOIN customer_credit_note_refund_matches m ON m.refund_id=r.id LEFT JOIN accounting_moves bm ON bm.id=m.accounting_move_id WHERE r.credit_note_id=:credit_note ORDER BY r.payment_date DESC,r.id DESC');$refunds->execute(['credit_note'=>$id]);$invoice['refunds']=$refunds->fetchAll();}
        else $invoice['refunds']=[];
        if (!$canReadAccounting) {
            foreach ($invoice['payments'] as &$payment) {
                foreach (['accounting_move_name','accounting_move_state','bank_move_name','bank_move_state'] as $field) $payment[$field] = null;
            }
            unset($payment);
        }
        return $invoice;
    }

    public function createAccount(array $input, UserContext $user, Authorization $authorization, int $actorId, string $remoteAddress): array
    {
        $unknown = array_diff(array_keys($input), ['company_id','code','name','account_type','allow_reconciliation']);
        if ($unknown) throw new InvalidArgumentException('Unsupported account fields: ' . implode(', ',$unknown));
        $companyId = $this->company($user,$authorization,$input['company_id'] ?? null);
        $code = strtoupper(trim((string)($input['code'] ?? ''))); $name = trim((string)($input['name'] ?? '')); $type = (string)($input['account_type'] ?? '');
        if (!preg_match('/^[A-Z0-9._-]{1,32}$/D',$code)) throw new InvalidArgumentException('Account Code must use 1–32 letters, digits, dots, underscores or hyphens.');
        if ($name === '' || mb_strlen($name)>190) throw new InvalidArgumentException('Account Name is required and must be 190 characters or fewer.');
        if (!in_array($type,self::ACCOUNT_TYPES,true)) throw new InvalidArgumentException('Select a valid account type.');
        $reconcile = $this->boolean($input['allow_reconciliation'] ?? false,'Allow Reconciliation');
        $this->pdo->beginTransaction();
        try {
            $this->pdo->prepare('INSERT INTO accounting_accounts (company_id,code,name,account_type,allow_reconciliation) VALUES (:company_id,:code,:name,:type,:reconcile)')->execute(['company_id'=>$companyId,'code'=>$code,'name'=>$name,'type'=>$type,'reconcile'=>$reconcile?1:0]);
            $id=(int)$this->pdo->lastInsertId();
            $this->audit($companyId,$actorId,$id,'accounting_account','accounting_account_created',null,['code'=>$code,'name'=>$name,'account_type'=>$type],$remoteAddress);
            $this->pdo->commit();
        } catch(Throwable $error) { if($this->pdo->inTransaction())$this->pdo->rollBack(); throw $error; }
        $query=$this->pdo->prepare('SELECT id,code,name,account_type,allow_reconciliation FROM accounting_accounts WHERE id=:id');$query->execute(['id'=>$id]);return $query->fetch()?:[];
    }

    public function createJournal(array $input, UserContext $user, Authorization $authorization, int $actorId, string $remoteAddress): array
    {
        $unknown = array_diff(array_keys($input), ['company_id','code','name','journal_type','default_account_id','outstanding_receipts_account_id','outstanding_payments_account_id']);
        if ($unknown) throw new InvalidArgumentException('Unsupported journal fields: ' . implode(', ',$unknown));
        $companyId=$this->company($user,$authorization,$input['company_id']??null); $code=strtoupper(trim((string)($input['code']??''))); $name=trim((string)($input['name']??''));
        $type=(string)($input['journal_type']??'sale');
        if(!preg_match('/^[A-Z0-9_-]{1,16}$/D',$code))throw new InvalidArgumentException('Journal Code must use 1–16 letters, digits, underscores or hyphens.');
        if($name===''||mb_strlen($name)>120)throw new InvalidArgumentException('Journal Name is required and must be 120 characters or fewer.');
        if(!in_array($type,['sale','purchase','bank','cash','general'],true))throw new InvalidArgumentException('Select a Sales, Purchase, Bank, Cash, or General journal type.');
        $defaultAccountId=null;$outstandingAccountId=null;$outstandingPaymentsAccountId=null;
        if(in_array($type,['bank','cash'],true)){
            $defaultAccountId=$this->positiveId($input['default_account_id']??null,'Bank/Cash Account');$outstandingAccountId=$this->positiveId($input['outstanding_receipts_account_id']??null,'Outstanding Receipts Account');
            $defaultAccount=$this->account($defaultAccountId,$companyId);$outstandingAccount=$this->account($outstandingAccountId,$companyId);
            if(!$defaultAccount||!in_array($defaultAccount['account_type'],['asset_cash','asset_current'],true))throw new InvalidArgumentException('Bank/Cash Account must be an active cash or current-asset account in this company.');
            if(!$outstandingAccount||!in_array($outstandingAccount['account_type'],['asset_current','asset_cash'],true)||$outstandingAccountId===$defaultAccountId)throw new InvalidArgumentException('Outstanding Receipts Account must be a different active current-asset account in this company.');
            $outgoingRaw=$input['outstanding_payments_account_id']??null;
            if($outgoingRaw!==null&&$outgoingRaw!==''){$outstandingPaymentsAccountId=$this->positiveId($outgoingRaw,'Outstanding Payments Account');$outgoingAccount=$this->account($outstandingPaymentsAccountId,$companyId);if(!$outgoingAccount||!in_array($outgoingAccount['account_type'],['asset_current','asset_cash'],true)||in_array($outstandingPaymentsAccountId,[$defaultAccountId,$outstandingAccountId],true))throw new InvalidArgumentException('Outstanding Payments Account must be a distinct active cash or current-asset account in this company.');}
        } elseif (!empty($input['outstanding_payments_account_id'])) {
            throw new InvalidArgumentException('Outstanding Payments Account is only configured on a Bank/Cash journal.');
        }
        $this->pdo->beginTransaction();
        try{
            $this->pdo->prepare('INSERT INTO accounting_journals (company_id,code,name,journal_type,default_account_id,outstanding_receipts_account_id,outstanding_payments_account_id,created_by) VALUES (:company_id,:code,:name,:type,:default_account,:outstanding_account,:outstanding_payments,:actor)')->execute(['company_id'=>$companyId,'code'=>$code,'name'=>$name,'type'=>$type,'default_account'=>$defaultAccountId,'outstanding_account'=>$outstandingAccountId,'outstanding_payments'=>$outstandingPaymentsAccountId,'actor'=>$actorId]);
            $id=(int)$this->pdo->lastInsertId();$this->audit($companyId,$actorId,$id,'accounting_journal','accounting_journal_created',null,['code'=>$code,'name'=>$name,'journal_type'=>$type],$remoteAddress);$this->pdo->commit();
        }catch(Throwable $error){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $error;}
        $query=$this->pdo->prepare('SELECT id,code,name,journal_type,default_account_id,outstanding_receipts_account_id,outstanding_payments_account_id FROM accounting_journals WHERE id=:id');$query->execute(['id'=>$id]);return $query->fetch()?:[];
    }

    public function createFromSalesOrder(int $salesOrderId, UserContext $user, Authorization $authorization, int $actorId, string $remoteAddress): array
    {
        $this->pdo->beginTransaction();
        try {
            $orderQuery=$this->pdo->prepare('SELECT so.*,c.receivable_account_id,c.customer_payment_terms_id,co.currency_code AS company_currency,cur.decimal_places,pt.due_days FROM sales_orders so JOIN contacts c ON c.id=so.partner_contact_id JOIN companies co ON co.id=so.company_id JOIN currencies cur ON cur.currency_code=so.currency_code LEFT JOIN payment_terms pt ON pt.id=so.payment_terms_id WHERE so.id=:id FOR UPDATE');
            $orderQuery->execute(['id'=>$salesOrderId]);$order=$orderQuery->fetch();
