            $journalQuery=$this->pdo->prepare("SELECT id FROM accounting_journals WHERE company_id=:company_id AND active=1 AND journal_type='sale' ORDER BY id LIMIT 1");$journalQuery->execute(['company_id'=>$order['company_id']]);$journalId=$journalQuery->fetchColumn();
            if($journalId===false)throw new InvalidArgumentException('Create an active Sales Journal for this company before invoicing.');
            $sourceLines=$this->pdo->prepare('SELECT l.id,l.product_id,l.uom_id,l.description,l.quantity,l.invoice_policy,l.unit_price,l.discount_percent,l.tax_id,l.tax_name_snapshot,l.tax_rate_snapshot,l.tax_included_snapshot,l.subtotal,l.tax_amount,p.product_type FROM sales_order_lines l JOIN products p ON p.id=l.product_id WHERE l.order_id=:id ORDER BY l.sequence,l.id');$sourceLines->execute(['id'=>$salesOrderId]);$lines=$sourceLines->fetchAll();
            if(!$lines)throw new InvalidArgumentException('The confirmed Sales Order has no lines.');
            $places=(int)$order['decimal_places'];if($places<0||$places>4)throw new InvalidArgumentException('The company currency precision is unsupported for invoice posting.');
            $invoiceDate=date('Y-m-d');$dueDays=max(0,(int)($order['due_days']??0));$dueDate=date('Y-m-d',strtotime($invoiceDate.' +'.$dueDays.' days'));
            $invoiceCount=$this->pdo->prepare("SELECT COUNT(*) FROM customer_invoices WHERE sales_order_id=:sales_order_id AND document_type='invoice'");$invoiceCount->execute(['sales_order_id'=>$salesOrderId]);$sequence=(int)$invoiceCount->fetchColumn()+1;
            $name='Draft/SO'.$salesOrderId.($sequence>1?'-'.$sequence:'');
            $billedQuery=$this->pdo->prepare("SELECT il.sales_order_line_id,CAST(COALESCE(SUM(il.quantity),0) AS DECIMAL(20,6)) AS quantity,CAST(COALESCE(SUM(il.subtotal),0) AS DECIMAL(20,6)) AS subtotal,CAST(COALESCE(SUM(il.tax_amount),0) AS DECIMAL(20,6)) AS tax_amount FROM customer_invoice_lines il JOIN customer_invoices i ON i.id=il.invoice_id WHERE i.sales_order_id=:order_id AND i.document_type='invoice' AND i.state='posted' GROUP BY il.sales_order_line_id");$billedQuery->execute(['order_id'=>$salesOrderId]);$billedByLine=[];foreach($billedQuery->fetchAll() as $billed)$billedByLine[(int)$billed['sales_order_line_id']]=$billed;
            $deliveredQuery=$this->pdo->prepare("SELECT CAST(COALESCE(SUM(CASE WHEN m.return_of_move_id IS NULL THEN m.done_quantity ELSE 0-m.done_quantity END),0) AS DECIMAL(20,6)) FROM stock_moves m WHERE m.company_id=:company AND m.source_line_model='sales_order_line' AND m.source_line_id=:line AND m.state='done'");
            $prepared=[];$untaxedMinor=0;$taxMinor=0;
            foreach($lines as $index=>$line){
                $orderedQuantity=(string)$line['quantity'];$already=$billedByLine[(int)$line['id']]??['quantity'=>'0.000000','subtotal'=>'0.000000','tax_amount'=>'0.000000'];$alreadyQuantity=(string)$already['quantity'];
                if($line['invoice_policy']==='delivered'){
