                }else{$eligibleQuantity=$orderedQuantity;}
                $remainingEligible=$this->maxZeroDecimal($this->subtractDecimal($eligibleQuantity,$alreadyQuantity));$remainingOrdered=$this->maxZeroDecimal($this->subtractDecimal($orderedQuantity,$alreadyQuantity));$quantity=$this->minDecimal($orderedQuantity,$remainingEligible);
                if($this->compareDecimal($quantity,'0.000000')<=0)continue;
                $sourceSubtotalMinor=$this->minor((string)$line['subtotal'],$places);$sourceTaxMinor=$this->minor((string)$line['tax_amount'],$places);
                $alreadySubtotalMinor=$this->minor((string)$already['subtotal'],$places);$alreadyTaxMinor=$this->minor((string)$already['tax_amount'],$places);
