            $this->pdo->prepare('INSERT INTO customer_invoices (company_id,name,sales_order_id,partner_contact_id,invoice_contact_id,journal_id,currency_code,invoice_date,due_date,state,untaxed_amount,tax_amount,total_amount,created_by,updated_by) VALUES (:company_id,:name,:order_id,:partner,:invoice_contact,:journal,:currency,:invoice_date,:due_date,\'draft\',:untaxed,:tax,:total,:created_by,:updated_by)')->execute([
                'company_id'=>$order['company_id'],'name'=>$name,'order_id'=>$salesOrderId,'partner'=>$order['partner_contact_id'],'invoice_contact'=>$order['invoice_contact_id'],'journal'=>$journalId,'currency'=>$order['currency_code'],'invoice_date'=>$invoiceDate,'due_date'=>$dueDate,'untaxed'=>$this->decimalFromMinor($untaxedMinor,$places),'tax'=>$this->decimalFromMinor($taxMinor,$places),'total'=>$this->decimalFromMinor($totalMinor,$places),'created_by'=>$actorId,'updated_by'=>$actorId]);
