    }

    public function createDirectInvoice(array $input,UserContext $user,Authorization $authorization,int $actorId,string $remoteAddress):array
    {
        $unknown=array_diff(array_keys($input),['company_id','partner_contact_id','invoice_contact_id','invoice_date','due_date','lines']);
        if($unknown)throw new InvalidArgumentException('Unsupported direct invoice fields: '.implode(', ',$unknown));
        $companyId=$this->company($user,$authorization,$input['company_id']??null);
        $partnerId=$this->positiveId($input['partner_contact_id']??null,'Customer');
        $invoiceContactId=$this->positiveId($input['invoice_contact_id']??$partnerId,'Invoice Contact');
        $invoiceDate=$this->date($input['invoice_date']??null,'Invoice Date');
        $dueDate=$this->date($input['due_date']??$invoiceDate,'Due Date');
        if($dueDate<$invoiceDate)throw new InvalidArgumentException('Due Date cannot be earlier than Invoice Date.');
        $rows=$input['lines']??null;
