            $billTo=$this->pdo->prepare('SELECT id FROM contacts WHERE id=:invoice_contact_id AND active=1 AND (id=:partner_self OR parent_contact_id=:partner_parent) AND (company_id IS NULL OR company_id=:company) LIMIT 1');
            $billTo->execute(['invoice_contact_id'=>$invoiceContactId,'partner_self'=>$partnerId,'partner_parent'=>$partnerId,'company'=>$companyId]);
            if(!$billTo->fetchColumn())throw new InvalidArgumentException('Invoice Contact must be the Customer or one of its active child Contacts.');
            $company=$this->pdo->prepare('SELECT co.currency_code,cur.decimal_places FROM companies co JOIN currencies cur ON cur.currency_code=co.currency_code WHERE co.id=:company AND co.active=1');
            $company->execute(['company'=>$companyId]);$companyRow=$company->fetch();
            if(!$companyRow)throw new InvalidArgumentException('Select an active company with a configured currency.');
            $places=(int)$companyRow['decimal_places'];if($places<0||$places>4)throw new InvalidArgumentException('The company currency precision is unsupported for invoice posting.');
            $journal=$this->pdo->prepare("SELECT id FROM accounting_journals WHERE company_id=:company AND active=1 AND journal_type='sale' ORDER BY id LIMIT 1");
            $journal->execute(['company'=>$companyId]);$journalId=$journal->fetchColumn();
            if($journalId===false)throw new InvalidArgumentException('Create an active Sales Journal for this company before invoicing.');
            $productQuery=$this->pdo->prepare('SELECT p.id,p.name,p.product_type,p.uom_id,p.list_price,u.category_id FROM products p JOIN units_of_measure u ON u.id=p.uom_id WHERE p.id=:product AND p.company_id=:company AND p.active=1 AND p.sale_ok=1 LIMIT 1');
            $unitQuery=$this->pdo->prepare('SELECT u.category_id,u.company_id,u.active,c.active AS category_active,c.company_id AS category_company FROM units_of_measure u JOIN uom_categories c ON c.id=u.category_id WHERE u.id=:unit LIMIT 1');
            $taxQuery=$this->pdo->prepare('SELECT name,amount,price_included FROM sales_taxes WHERE id=:id AND active=1 AND (company_id IS NULL OR company_id=:company) LIMIT 1');
            $prepared=[];$untaxedMinor=0;$taxMinorTotal=0;$totalMinor=0;
            foreach(array_values($rows) as $index=>$row){
                if(!is_array($row))throw new InvalidArgumentException('Each direct invoice line must be an object.');
                $extra=array_diff(array_keys($row),['product_id','uom_id','description','quantity','unit_price','discount_percent','tax_id']);
                if($extra)throw new InvalidArgumentException('Unsupported direct invoice line fields: '.implode(', ',$extra));
                $productId=$this->positiveId($row['product_id']??null,'Product');$productQuery->execute(['product'=>$productId,'company'=>$companyId]);$product=$productQuery->fetch();
                if(!$product)throw new InvalidArgumentException('Select an active, saleable product from this company.');
                $uomId=isset($row['uom_id'])&&$row['uom_id']!==''?$this->positiveId($row['uom_id'],'Unit of Measure'):(int)$product['uom_id'];
                $unitQuery->execute(['unit'=>$uomId]);$unit=$unitQuery->fetch();
                if(!$unit||!(int)$unit['active']||!(int)$unit['category_active']||(int)$unit['category_id']!==(int)$product['category_id']||($unit['company_id']!==null&&(int)$unit['company_id']!==$companyId)||($unit['category_company']!==null&&(int)$unit['category_company']!==$companyId))throw new InvalidArgumentException('Each invoice line must use an active Unit of Measure in the product unit category.');
