                $description=trim((string)($row['description']??''));if($description==='')$description=(string)$product['name'];if(mb_strlen($description)>500)throw new InvalidArgumentException('Line Description must be 500 characters or fewer.');
                $rate=(string)($tax['amount']??'0');$included=(int)($tax['price_included']??0);
                $gross=$this->calculate('CAST(ROUND(CAST(:quantity AS DECIMAL(20,6))*CAST(:price AS DECIMAL(20,6))*(1-CAST(:discount AS DECIMAL(10,4))/100),6) AS DECIMAL(20,6))',['quantity'=>$quantity,'price'=>$price,'discount'=>$discount]);
                $components=$this->pdo->prepare('SELECT CAST(ROUND(CASE WHEN x.included=1 AND x.rate>0 THEN x.gross-(x.gross/(1+x.rate/100)) ELSE x.gross*x.rate/100 END,6) AS DECIMAL(20,6)) AS tax_amount,CAST(ROUND(CASE WHEN x.included=1 THEN x.gross-(CASE WHEN x.rate>0 THEN x.gross-(x.gross/(1+x.rate/100)) ELSE 0 END) ELSE x.gross END,6) AS DECIMAL(20,6)) AS subtotal FROM (SELECT CAST(:gross AS DECIMAL(20,6)) AS gross,CAST(:rate AS DECIMAL(10,4)) AS rate,CAST(:included AS UNSIGNED) AS included) x');
                $components->execute(['gross'=>$gross,'rate'=>$rate,'included'=>$included]);$amounts=$components->fetch();
                $lineSubtotalMinor=$this->minor((string)$amounts['subtotal'],$places);$lineTaxMinor=$this->minor((string)$amounts['tax_amount'],$places);$lineTotalMinor=$lineSubtotalMinor+$lineTaxMinor;
                if($lineTotalMinor<0)throw new InvalidArgumentException('Invoice line total exceeds the supported amount.');
                $untaxedMinor+=$lineSubtotalMinor;$taxMinorTotal+=$lineTaxMinor;$totalMinor+=$lineTotalMinor;
                $prepared[]=['sequence'=>($index+1)*10,'product_id'=>$productId,'uom_id'=>$uomId,'description'=>$description,'quantity'=>$quantity,'unit_price'=>$price,'discount_percent'=>$discount,'tax_id'=>$taxId,'tax_name'=>$tax['name']??null,'tax_rate'=>number_format((float)$rate,4,'.',''),'tax_included'=>$included,'subtotal'=>$this->decimalFromMinor($lineSubtotalMinor,$places),'tax_amount'=>$this->decimalFromMinor($lineTaxMinor,$places),'total'=>$this->decimalFromMinor($lineTotalMinor,$places)];
            }
            if($totalMinor<=0)throw new InvalidArgumentException('Invoice total must be greater than zero before posting.');
            $name='Draft/DIR/'.str_replace('-','',$invoiceDate).'/'.strtoupper(bin2hex(random_bytes(3)));
            $this->pdo->prepare("INSERT INTO customer_invoices (company_id,name,sales_order_id,partner_contact_id,invoice_contact_id,journal_id,currency_code,invoice_date,due_date,state,untaxed_amount,tax_amount,total_amount,created_by,updated_by) VALUES (:company,:name,NULL,:partner,:invoice_contact,:journal,:currency,:invoice_date,:due_date,'draft',:untaxed,:tax,:total,:created_by,:updated_by)")->execute(['company'=>$companyId,'name'=>$name,'partner'=>$partnerId,'invoice_contact'=>$invoiceContactId,'journal'=>$journalId,'currency'=>$companyRow['currency_code'],'invoice_date'=>$invoiceDate,'due_date'=>$dueDate,'untaxed'=>$this->decimalFromMinor($untaxedMinor,$places),'tax'=>$this->decimalFromMinor($taxMinorTotal,$places),'total'=>$this->decimalFromMinor($totalMinor,$places),'created_by'=>$actorId,'updated_by'=>$actorId]);
            $invoiceId=(int)$this->pdo->lastInsertId();
            $lineInsert=$this->pdo->prepare('INSERT INTO customer_invoice_lines (invoice_id,sequence,sales_order_line_id,product_id,uom_id,description,quantity,unit_price,discount_percent,tax_id,tax_name_snapshot,tax_rate_snapshot,tax_included_snapshot,subtotal,tax_amount,total) VALUES (:invoice,:sequence,NULL,:product,:uom,:description,:quantity,:price,:discount,:tax_id,:tax_name,:tax_rate,:tax_included,:subtotal,:tax,:total)');
            foreach($prepared as $line)$lineInsert->execute(['invoice'=>$invoiceId,'sequence'=>$line['sequence'],'product'=>$line['product_id'],'uom'=>$line['uom_id'],'description'=>$line['description'],'quantity'=>$line['quantity'],'price'=>$line['unit_price'],'discount'=>$line['discount_percent'],'tax_id'=>$line['tax_id'],'tax_name'=>$line['tax_name'],'tax_rate'=>$line['tax_rate'],'tax_included'=>$line['tax_included'],'subtotal'=>$line['subtotal'],'tax'=>$line['tax_amount'],'total'=>$line['total']]);
            $this->audit($companyId,$actorId,$invoiceId,'customer_invoice','customer_invoice_created',null,['name'=>$name,'origin'=>'direct','partner_contact_id'=>$partnerId,'invoice_date'=>$invoiceDate,'due_date'=>$dueDate,'state'=>'draft','total_amount'=>$this->decimalFromMinor($totalMinor,$places)],$remoteAddress);
            $this->pdo->commit();
        }catch(Throwable $error){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$error;}
        return$this->find($invoiceId,$user,$authorization)??throw new InvalidArgumentException('Created direct invoice could not be reloaded.');
    }

    public function createCreditNote(int $invoiceId,array $input,UserContext $user,Authorization $authorization,int $actorId,string $remoteAddress):array
    {
        $unknown=array_diff(array_keys($input),['credit_note_date','reason','lines']);if($unknown)throw new InvalidArgumentException('Unsupported credit note fields: '.implode(', ',$unknown));
        $creditDate=$this->date($input['credit_note_date']??null,'Credit Note Date');$reason=trim((string)($input['reason']??''));if($reason===''||mb_strlen($reason)>190)throw new InvalidArgumentException('Credit Note Reason is required and must be 190 characters or fewer.');
        $source=$this->find($invoiceId,$user,$authorization);if(!$source)throw new InvalidArgumentException('Customer invoice was not found.');if(($source['document_type']??'invoice')!=='invoice'||$source['state']!=='posted')throw new InvalidArgumentException('A credit note can only be created from a posted customer invoice.');if(!empty($source['sales_order_id'])&&!$authorization->allowsForCompany('sales.read',(int)$source['company_id']))throw new AccessDeniedException('Sales read access is required to credit a Sales Order invoice.');
        $requested=[];if(array_key_exists('lines',$input)){if(!is_array($input['lines'])||!array_is_list($input['lines'])||!$input['lines'])throw new InvalidArgumentException('Select at least one invoice line and a positive credit quantity.');foreach($input['lines'] as $item){if(!is_array($item)||array_diff(array_keys($item),['invoice_line_id','quantity','return_quantity']))throw new InvalidArgumentException('Each credit note line needs an invoice_line_id, quantity, and optional return_quantity.');$lineId=$this->positiveId($item['invoice_line_id']??null,'Invoice Line');$quantity=trim((string)($item['quantity']??''));$returnQuantity=trim((string)($item['return_quantity']??'0'));if(!preg_match('/^(?:0|[1-9][0-9]{0,11})(?:\.[0-9]{1,6})?$/D',$quantity)||$this->compareDecimal($quantity,'0.000000')<=0)throw new InvalidArgumentException('Each credit quantity must be positive with no more than six decimal places.');if(!preg_match('/^(?:0|[1-9][0-9]{0,11})(?:\.[0-9]{1,6})?$/D',$returnQuantity))throw new InvalidArgumentException('Returned Quantity must be nonnegative with no more than six decimal places.');if(isset($requested[$lineId]))throw new InvalidArgumentException('An invoice line can appear only once in a credit note.');$requested[$lineId]=['quantity'=>$quantity,'return_quantity'=>$returnQuantity];}}
        $this->pdo->beginTransaction();
        try{
            $sourceLock=$this->pdo->prepare("SELECT i.*,co.currency_code AS company_currency,cur.decimal_places FROM customer_invoices i JOIN companies co ON co.id=i.company_id JOIN currencies cur ON cur.currency_code=i.currency_code WHERE i.id=:id AND i.company_id=:company AND i.document_type='invoice' AND i.state='posted' FOR UPDATE");$sourceLock->execute(['id'=>$invoiceId,'company'=>$source['company_id']]);$current=$sourceLock->fetch();if(!$current)throw new InvalidArgumentException('Credit notes require a posted source invoice in the same company.');
            if($current['company_currency']!==$current['currency_code'])throw new InvalidArgumentException('Credit notes must use the company currency until exchange rates are configured.');
            $draftQuery=$this->pdo->prepare("SELECT name FROM customer_invoices WHERE company_id=:company AND document_type='credit_note' AND reversal_of_invoice_id=:invoice AND state='draft' ORDER BY id LIMIT 1 FOR UPDATE");$draftQuery->execute(['company'=>$current['company_id'],'invoice'=>$invoiceId]);$existingDraft=$draftQuery->fetchColumn();if($existingDraft!==false)throw new InvalidArgumentException('Post or discard the existing draft credit note '.$existingDraft.' before creating another one for this invoice.');
            $accountQuery=$this->pdo->prepare("SELECT DISTINCT ml.account_id,a.account_type FROM accounting_move_lines ml JOIN accounting_accounts a ON a.id=ml.account_id WHERE ml.move_id=:move AND a.company_id=:company ORDER BY ml.account_id");$accountQuery->execute(['move'=>$current['accounting_move_id'],'company'=>$current['company_id']]);$sourceRevenueAccounts=[];$sourceTaxAccounts=[];foreach($accountQuery->fetchAll() as $account){if(str_starts_with($account['account_type'],'income'))$sourceRevenueAccounts[]=(int)$account['account_id'];elseif(str_starts_with($account['account_type'],'liability'))$sourceTaxAccounts[]=(int)$account['account_id'];}
            $linesQuery=$this->pdo->prepare('SELECT il.*,p.product_type,u.factor_to_reference AS invoice_uom_factor,pu.factor_to_reference AS product_uom_factor FROM customer_invoice_lines il JOIN products p ON p.id=il.product_id JOIN units_of_measure u ON u.id=il.uom_id JOIN units_of_measure pu ON pu.id=p.uom_id WHERE il.invoice_id=:invoice ORDER BY il.sequence,il.id FOR UPDATE');$linesQuery->execute(['invoice'=>$invoiceId]);$sourceLines=$linesQuery->fetchAll();if(!$sourceLines)throw new InvalidArgumentException('The source invoice has no creditable lines.');
            $creditedQuery=$this->pdo->prepare("SELECT cl.reversal_of_line_id,CAST(COALESCE(SUM(cl.quantity),0) AS DECIMAL(20,6)) AS quantity,CAST(COALESCE(SUM(cl.subtotal),0) AS DECIMAL(20,6)) AS subtotal,CAST(COALESCE(SUM(cl.tax_amount),0) AS DECIMAL(20,6)) AS tax_amount FROM customer_invoice_lines cl JOIN customer_invoices cn ON cn.id=cl.invoice_id WHERE cn.company_id=:company AND cn.document_type='credit_note' AND cn.reversal_of_invoice_id=:invoice AND cn.state='posted' GROUP BY cl.reversal_of_line_id");$creditedQuery->execute(['company'=>$current['company_id'],'invoice'=>$invoiceId]);$credited=[];foreach($creditedQuery->fetchAll() as $row)$credited[(int)$row['reversal_of_line_id']]=$row;
            $sourceById=[];foreach($sourceLines as $line)$sourceById[(int)$line['id']]=$line;
