            else foreach($sourceLines as $line){$lineId=(int)$line['id'];$already=$credited[$lineId]??['quantity'=>'0.000000'];$remaining=$this->maxZeroDecimal($this->subtractDecimal((string)$line['quantity'],(string)$already['quantity']));if($this->compareDecimal($remaining,'0.000000')>0)$requested[$lineId]=['quantity'=>$remaining,'return_quantity'=>'0.000000'];}
