            $journal=$this->pdo->prepare("SELECT id,code FROM accounting_journals WHERE id=:id AND company_id=:company_id AND active=1 AND journal_type='sale' LIMIT 1");$journal->execute(['id'=>$current['journal_id'],'company_id'=>$current['company_id']]);if(!$journal->fetch())throw new InvalidArgumentException('The invoice Sales Journal is no longer active for this company.');
            $lineQuery=$this->pdo->prepare('SELECT il.*,p.name AS product_name,p.income_account_id,p.product_type,p.category_id,p.cost_price,sol.invoice_policy AS sales_invoice_policy,sol.quantity AS sales_order_quantity,source_unit.factor_to_reference AS sales_order_uom_factor,product_unit.name AS product_uom_name,unit.factor_to_reference AS invoice_uom_factor,product_unit.factor_to_reference AS product_uom_factor,COALESCE(o.valuation_method,s.valuation_method,\'periodic\') AS effective_valuation_method,COALESCE(o.costing_method,s.costing_method,c.costing_method) AS effective_costing_method,COALESCE(o.valuation_account_id,s.valuation_account_id) AS effective_valuation_account_id,COALESCE(o.expense_account_id,s.expense_adjustment_account_id) AS effective_cost_account_id,COALESCE(s.accounting_standard,\'continental\') AS accounting_standard,t.account_id AS tax_account_id FROM customer_invoice_lines il JOIN products p ON p.id=il.product_id JOIN product_categories c ON c.id=p.category_id JOIN units_of_measure unit ON unit.id=il.uom_id JOIN units_of_measure product_unit ON product_unit.id=p.uom_id LEFT JOIN sales_order_lines sol ON sol.id=il.sales_order_line_id LEFT JOIN units_of_measure source_unit ON source_unit.id=sol.uom_id LEFT JOIN inventory_accounting_settings s ON s.company_id=:company_id LEFT JOIN product_category_accounting_overrides o ON o.company_id=:override_company_id AND o.category_id=p.category_id LEFT JOIN sales_taxes t ON t.id=il.tax_id WHERE il.invoice_id=:invoice_id ORDER BY il.sequence,il.id');$lineQuery->execute(['company_id'=>$current['company_id'],'override_company_id'=>$current['company_id'],'invoice_id'=>$id]);$lines=$lineQuery->fetchAll();if(!$lines)throw new InvalidArgumentException('An invoice needs at least one line before posting.');
