                    if($this->compareDecimal($cost['quantity'],$expectedQuantity)<0)throw new InvalidArgumentException('Complete the delivery quantity for "'.$line['product_name'].'" before posting this Perpetual invoice so its cost matches the stock valuation.');
                    $costMinor=$this->minor($cost['amount'],$places);
                    $costAllocations=$this->normalizeLayerCostAllocations($cost['allocations']??[],$costMinor,$places);
                    if($costMinor>0){$costTotals[$costId]=($costTotals[$costId]??0)+$costMinor;$stockTotals[$stockId]=($stockTotals[$stockId]??0)+$costMinor;}
                    $costSnapshots[]=['line_id'=>(int)$line['id'],'quantity'=>$expectedQuantity,'amount'=>$this->decimalFromMinor($costMinor,$places),'cost_account_id'=>$costId,'stock_account_id'=>$stockId,'costing_method'=>$cost['costing_method'],'cost_source'=>'stock_move','allocations'=>$costAllocations];
                }else{
                    $costSnapshots[]=['line_id'=>(int)$line['id'],'quantity'=>'0.000000','amount'=>'0.000000','cost_account_id'=>null,'stock_account_id'=>null,'costing_method'=>null,'cost_source'=>null,'allocations'=>[]];
                }
            }
            $headerUntaxed=$this->minor((string)$current['untaxed_amount'],$places);$headerTax=$this->minor((string)$current['tax_amount'],$places);$total=$this->minor((string)$current['total_amount'],$places);
            if($lineUntaxedTotal!==$headerUntaxed||$lineTaxTotal!==$headerTax||$headerUntaxed+$headerTax!==$total)throw new InvalidArgumentException('Invoice totals do not match the saved invoice lines.');
            if($total<1)throw new InvalidArgumentException('Invoice total must be greater than zero before posting.');
            $postedName=$this->nextInvoiceNumber((int)$current['company_id'],(int)substr((string)$current['invoice_date'],0,4));
            $this->pdo->prepare('UPDATE customer_invoices SET name=:name WHERE id=:id AND state=\'draft\'')->execute(['name'=>$postedName,'id'=>$id]);
            $current['name']=$postedName;
            $accountingLines[]=['sequence'=>$sequence,'account_id'=>$receivableId,'contact_id'=>(int)$current['partner_contact_id'],'label'=>'Receivable · '.$current['name'],'debit'=>$total,'credit'=>0];$sequence+=10;$debitTotal+=$total;
            foreach($costTotals as $accountId=>$amount){$label=$lines[0]['accounting_standard']==='anglo_saxon'?'Cost of Goods Sold · '.$current['name']:'Inventory Expense · '.$current['name'];$accountingLines[]=['sequence'=>$sequence,'account_id'=>$accountId,'contact_id'=>null,'label'=>$label,'debit'=>$amount,'credit'=>0];$sequence+=10;$debitTotal+=$amount;}
            foreach($stockTotals as $accountId=>$amount){$accountingLines[]=['sequence'=>$sequence,'account_id'=>$accountId,'contact_id'=>null,'label'=>'Stock Valuation · '.$current['name'],'debit'=>0,'credit'=>$amount];$sequence+=10;$creditTotal+=$amount;}
            foreach($revenueTotals as $accountId=>$amount){$accountingLines[]=['sequence'=>$sequence,'account_id'=>$accountId,'contact_id'=>null,'label'=>'Sales Revenue · '.$current['name'],'debit'=>0,'credit'=>$amount];$sequence+=10;$creditTotal+=$amount;}
            foreach($taxTotals as $accountId=>$amount){$accountingLines[]=['sequence'=>$sequence,'account_id'=>$accountId,'contact_id'=>null,'label'=>'Tax Payable · '.$current['name'],'debit'=>0,'credit'=>$amount];$sequence+=10;$creditTotal+=$amount;}
