    }

    public function cancelCreditNote(int $id,UserContext $user,Authorization $authorization,int $actorId,string $remoteAddress):array
    {
        $creditNote=$this->find($id,$user,$authorization);if(!$creditNote||($creditNote['document_type']??'')!=='credit_note')throw new InvalidArgumentException('Customer credit note was not found.');$this->pdo->beginTransaction();
        try{$lock=$this->pdo->prepare("SELECT id,company_id,name,state FROM customer_invoices WHERE id=:id AND company_id=:company AND document_type='credit_note' FOR UPDATE");$lock->execute(['id'=>$id,'company'=>$creditNote['company_id']]);$current=$lock->fetch();if(!$current||$current['state']!=='draft')throw new InvalidArgumentException('Only a draft credit note can be discarded.');$this->pdo->prepare("UPDATE customer_invoices SET state='cancelled',payment_state='not_applicable',amount_paid=0,amount_residual=0,updated_by=:actor WHERE id=:id AND company_id=:company AND state='draft'")->execute(['actor'=>$actorId,'id'=>$id,'company'=>$current['company_id']]);$this->audit((int)$current['company_id'],$actorId,$id,'customer_invoice','customer_credit_note_discarded',['state'=>'draft','name'=>$current['name']],['state'=>'cancelled'],$remoteAddress);$this->pdo->commit();}
        catch(Throwable $error){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $error;}
