    public function registerPayment(int $invoiceId,array $input,UserContext $user,Authorization $authorization,int $actorId,string $remoteAddress):array
    {
        $unknown=array_diff(array_keys($input),['journal_id','payment_date','amount','reference']);if($unknown)throw new InvalidArgumentException('Unsupported payment fields: '.implode(', ',$unknown));
        $date=$this->date($input['payment_date']??null,'Payment Date');$reference=trim((string)($input['reference']??''));if(mb_strlen($reference)>190)throw new InvalidArgumentException('Payment Reference must be 190 characters or fewer.');
        $invoice=$this->find($invoiceId,$user,$authorization);if(!$invoice)throw new InvalidArgumentException('Customer invoice was not found.');if(($invoice['document_type']??'invoice')!=='invoice')throw new InvalidArgumentException('Customer receipts can be registered only against invoices. Credit note refunds and applications are handled separately.');
        $this->pdo->beginTransaction();
        try{
            $lock=$this->pdo->prepare('SELECT i.*,co.currency_code AS company_currency,cur.decimal_places,c.receivable_account_id FROM customer_invoices i JOIN companies co ON co.id=i.company_id JOIN currencies cur ON cur.currency_code=i.currency_code JOIN contacts c ON c.id=i.partner_contact_id WHERE i.id=:id AND i.company_id=:company_id FOR UPDATE');$lock->execute(['id'=>$invoiceId,'company_id'=>$invoice['company_id']]);$current=$lock->fetch();
            if(!$current||$current['state']!=='posted')throw new InvalidArgumentException('Only a posted customer invoice can receive a payment.');
            \Erp\Modules\Accounting\AccountingDateGuard::lockAndAssertOpen($this->pdo,(int)$current['company_id'],$date);
            if($current['currency_code']!==$current['company_currency'])throw new InvalidArgumentException('Payment currency must match the company currency until exchange rates are configured.');
