            else{$amountMinor=$this->minor((string)($input['amount']??''),$places);}
            $paymentMinor=$this->minor((string)$payment['amount'],$places);if($amountMinor<1||$amountMinor!==$paymentMinor)throw new InvalidArgumentException('Bank Statement Amount must exactly match the registered payment amount.');
