            $matchId=(int)$this->pdo->lastInsertId();$moveName=sprintf('BNK%04d-%06d',(int)substr($date,0,4),$matchId);$moveReference=$reference.' · '.$payment['name'];
            $this->pdo->prepare("INSERT INTO accounting_moves (company_id,name,journal_id,move_type,reference_model,reference_id,reference,accounting_date,currency_code,state,total_debit,total_credit,created_by) VALUES (:company,:name,:journal,'bank_reconciliation','bank_statement_match',:match_id,:reference,:date,:currency,'draft',:debit,:credit,:actor)")->execute(['company'=>$companyId,'name'=>$moveName,'journal'=>$journalId,'match_id'=>$matchId,'reference'=>$moveReference,'date'=>$date,'currency'=>$payment['currency_code'],'debit'=>$this->decimalFromMinor($amountMinor,$places),'credit'=>$this->decimalFromMinor($amountMinor,$places),'actor'=>$actorId]);
            $moveId=(int)$this->pdo->lastInsertId();$amount=$this->decimalFromMinor($amountMinor,$places);$lineInsert=$this->pdo->prepare('INSERT INTO accounting_move_lines (move_id,sequence,account_id,contact_id,label,debit,credit,currency_code,amount_currency) VALUES (:move,:sequence,:account,NULL,:label,:debit,:credit,:currency,:amount_currency)');
            $lineInsert->execute(['move'=>$moveId,'sequence'=>10,'account'=>$payment['default_account_id'],'label'=>'Bank Statement · '.$reference,'debit'=>$amount,'credit'=>'0','currency'=>$payment['currency_code'],'amount_currency'=>$amount]);
            $lineInsert->execute(['move'=>$moveId,'sequence'=>20,'account'=>$payment['outstanding_receipts_account_id'],'label'=>'Clear Outstanding Receipts · '.$payment['name'],'debit'=>'0','credit'=>$amount,'currency'=>$payment['currency_code'],'amount_currency'=>'-'.$amount]);
            $this->pdo->prepare("UPDATE accounting_moves SET state='posted',posted_by=:actor,posted_at=UTC_TIMESTAMP() WHERE id=:id AND state='draft'")->execute(['actor'=>$actorId,'id'=>$moveId]);
            $this->pdo->prepare('UPDATE bank_statement_matches SET accounting_move_id=:move WHERE id=:id')->execute(['move'=>$moveId,'id'=>$matchId]);
            $this->pdo->prepare("UPDATE customer_payments SET state='paid',paid_at=UTC_TIMESTAMP() WHERE id=:id AND state='in_payment'")->execute(['id'=>$paymentId]);
            $paidAllocations=$this->pdo->prepare("SELECT COALESCE(SUM(a.amount),0) FROM invoice_payment_allocations a JOIN customer_payments p ON p.id=a.payment_id WHERE a.invoice_id=:invoice AND p.state='paid'");$paidAllocations->execute(['invoice'=>$invoiceId]);$paidAfterMatch=$this->minor((string)$paidAllocations->fetchColumn(),$places);
            $invoiceTotal=$this->minor((string)$payment['total_amount'],$places);$residual=$this->minor((string)$payment['amount_residual'],$places);$amountPaid=$this->minor((string)$payment['amount_paid'],$places);
            $credited=$this->minor((string)$payment['amount_credited'],$places);$paymentState=$residual===0?($paidAfterMatch+$credited>=$invoiceTotal?'paid':'in_payment'):($amountPaid+$credited>0?'partial':'not_paid');
