            $this->audit($companyId,$actorId,$matchId,'bank_statement_match','customer_payment_reconciled',null,['payment_id'=>$paymentId,'invoice_id'=>$invoiceId,'reference'=>$reference,'amount'=>$amount,'accounting_move_id'=>$moveId],$remoteAddress);
            $this->audit($companyId,$actorId,$paymentId,'customer_payment','customer_payment_reconciled',['state'=>'in_payment'],['state'=>'paid','bank_statement_match_id'=>$matchId],$remoteAddress);
            $this->audit($companyId,$actorId,$invoiceId,'customer_invoice','customer_invoice_reconciled',['payment_state'=>$payment['invoice_payment_state']],['payment_state'=>$paymentState],$remoteAddress);
            if($statementLineId!==null){$statementIdQuery=$this->pdo->prepare('SELECT statement_id FROM bank_statement_lines WHERE id=:id');$statementIdQuery->execute(['id'=>$statementLineId]);\Erp\Modules\Accounting\BankStatementRepository::refreshStatementState($this->pdo,(int)$statementIdQuery->fetchColumn());}
            $this->pdo->commit();
        }catch(Throwable $error){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $error;}
        return $this->find($invoiceId,$user,$authorization)??throw new InvalidArgumentException('The payment was reconciled but the invoice could not be reloaded.');
    }

    private function account(int $id,int $companyId): ?array
    {
        if($id<1)return null;$query=$this->pdo->prepare('SELECT id,code,name,account_type FROM accounting_accounts WHERE id=:id AND company_id=:company_id AND active=1 LIMIT 1');$query->execute(['id'=>$id,'company_id'=>$companyId]);return $query->fetch()?:null;
    }
    private function postedSalesProductQuantity(int $orderId,int $salesLineId,string $productFactor,int $excludeInvoiceId):string
    {
        $query=$this->pdo->prepare("SELECT CAST(COALESCE(SUM(CAST(il.quantity AS DECIMAL(20,6))*CAST(u.factor_to_reference AS DECIMAL(20,10))/CAST(:product_factor AS DECIMAL(20,10))),0) AS DECIMAL(20,6)) FROM customer_invoice_lines il JOIN customer_invoices i ON i.id=il.invoice_id JOIN units_of_measure u ON u.id=il.uom_id WHERE i.sales_order_id=:order_id AND i.document_type='invoice' AND il.sales_order_line_id=:sales_line_id AND i.state='posted' AND i.id<>:exclude_invoice");
        $query->execute(['product_factor'=>$productFactor,'order_id'=>$orderId,'sales_line_id'=>$salesLineId,'exclude_invoice'=>$excludeInvoiceId]);return(string)$query->fetchColumn();
    }
    private function deliveredSalesProductQuantity(int $companyId,int $salesLineId,string $productFactor):string
    {
        $query=$this->pdo->prepare("SELECT CAST(COALESCE(SUM((CASE WHEN m.return_of_move_id IS NULL THEN CAST(m.done_quantity AS DECIMAL(20,6)) ELSE 0-CAST(m.done_quantity AS DECIMAL(20,6)) END)*CAST(u.factor_to_reference AS DECIMAL(20,10))/CAST(:product_factor AS DECIMAL(20,10))),0) AS DECIMAL(20,6)) FROM stock_moves m JOIN units_of_measure u ON u.id=m.uom_id WHERE m.company_id=:company_id AND m.source_line_model='sales_order_line' AND m.source_line_id=:sales_line_id AND m.state='done'");
        $query->execute(['product_factor'=>$productFactor,'company_id'=>$companyId,'sales_line_id'=>$salesLineId]);return(string)$query->fetchColumn();
    }
    /** Allocate the next invoice quantity against the exact remaining cost layers for this Sales Order line. */
    private function deliveredSalesCostSlice(int $companyId,int $orderId,int $salesLineId,int $productId,string $method,string $offsetQuantity,string $requestedQuantity):array
    {
        $productLineCount=$this->pdo->prepare('SELECT COUNT(*) FROM sales_order_lines WHERE order_id=:order AND product_id=:product');$productLineCount->execute(['order'=>$orderId,'product'=>$productId]);$sameProductLines=(int)$productLineCount->fetchColumn();
        $legacyLayers=$this->pdo->prepare("SELECT CAST(COALESCE(SUM(0-v.quantity_delta),0) AS DECIMAL(20,6)) AS quantity FROM inventory_valuation_layers v JOIN stock_moves m ON m.id=v.stock_move_id WHERE v.company_id=:company AND v.product_id=:product AND v.source_model='sale_order' AND v.source_record_id=:order AND v.quantity_delta<0 AND m.origin_model='sale_order' AND m.origin_record_id=:origin_order");
        $legacyLayers->execute(['company'=>$companyId,'product'=>$productId,'order'=>$orderId,'origin_order'=>$orderId]);$legacyQuantity=(string)$legacyLayers->fetchColumn();
        if($sameProductLines>1&&!$this->decimalEquals($legacyQuantity,'0.000000'))throw new InvalidArgumentException('This order has older deliveries for a repeated product without line-level cost links. Review the delivery cost allocation before posting its Perpetual invoice.');
        $remainingLayerQuantity="GREATEST(0,CAST(0-v.quantity_delta AS DECIMAL(20,6))-COALESCE((SELECT SUM(CAST(rv.quantity_delta AS DECIMAL(20,6))) FROM inventory_valuation_layers rv JOIN stock_move_lines rml ON rml.id=rv.stock_move_line_id JOIN stock_moves rm ON rm.id=rml.move_id WHERE rml.return_of_move_line_id=v.stock_move_line_id AND rm.state='done'),0))";
        $remainingLayerValue="GREATEST(0,CAST(0-v.value_delta AS DECIMAL(20,6))-COALESCE((SELECT SUM(CAST(rv.value_delta AS DECIMAL(20,6))) FROM inventory_valuation_layers rv JOIN stock_move_lines rml ON rml.id=rv.stock_move_line_id JOIN stock_moves rm ON rm.id=rml.move_id WHERE rml.return_of_move_line_id=v.stock_move_line_id AND rm.state='done'),0))";
        $sql="SELECT v.id AS layer_id,CAST($remainingLayerQuantity AS DECIMAL(20,6)) AS quantity,CAST($remainingLayerValue AS DECIMAL(20,6)) AS amount FROM inventory_valuation_layers v WHERE v.company_id=:company_line AND v.product_id=:product_line AND v.source_model='sales_order_line' AND v.source_record_id=:line_id AND v.quantity_delta<0";
        $params=['company_line'=>$companyId,'product_line'=>$productId,'line_id'=>$salesLineId];
        if($sameProductLines===1){$sql.=" UNION ALL SELECT v.id AS layer_id,CAST($remainingLayerQuantity AS DECIMAL(20,6)) AS quantity,CAST($remainingLayerValue AS DECIMAL(20,6)) AS amount FROM inventory_valuation_layers v JOIN stock_moves m ON m.id=v.stock_move_id WHERE v.company_id=:company_legacy AND v.product_id=:product_legacy AND v.source_model='sale_order' AND v.source_record_id=:order_id AND v.quantity_delta<0 AND m.origin_model='sale_order' AND m.origin_record_id=:origin_order";$params+=['company_legacy'=>$companyId,'product_legacy'=>$productId,'order_id'=>$orderId,'origin_order'=>$orderId];}
        $sql.=' ORDER BY layer_id';$query=$this->pdo->prepare($sql);$query->execute($params);$layers=$query->fetchAll();
        $zero='0.000000';$skip=$this->maxZeroDecimal($offsetQuantity);$remaining=$this->maxZeroDecimal($requestedQuantity);$amount=$zero;$allocated=$zero;$allocations=[];
        foreach($layers as $layer){$layerQuantity=(string)$layer['quantity'];if($this->compareDecimal($layerQuantity,$zero)<=0)continue;if($this->compareDecimal($skip,$layerQuantity)>=0){$skip=$this->subtractDecimal($skip,$layerQuantity);continue;}$available=$this->maxZeroDecimal($this->subtractDecimal($layerQuantity,$skip));$take=$this->minDecimal($available,$remaining);if($this->compareDecimal($take,$zero)<=0)continue;$layerAmount=(string)$layer['amount'];$slice=$this->decimalEquals($take,$layerQuantity)&&$this->decimalEquals($skip,$zero)?$layerAmount:$this->calculate('CAST(ROUND(CAST(:amount AS DECIMAL(20,6))*CAST(:take AS DECIMAL(20,6))/NULLIF(CAST(:quantity AS DECIMAL(20,6)),0),6) AS DECIMAL(20,6))',['amount'=>$layerAmount,'take'=>$take,'quantity'=>$layerQuantity]);$amount=$this->addDecimal($amount,$slice);$allocated=$this->addDecimal($allocated,$take);$allocations[]=['valuation_layer_id'=>(int)$layer['layer_id'],'quantity'=>$take,'raw_amount'=>$slice];$remaining=$this->maxZeroDecimal($this->subtractDecimal($remaining,$take));$skip=$zero;if($this->compareDecimal($remaining,$zero)<=0)break;}
        return ['quantity'=>$allocated,'amount'=>$amount,'costing_method'=>$method,'allocations'=>$allocations];
    }
    private function normalizeLayerCostAllocations(array $allocations,int $costMinor,int $places):array
    {
        if(!$allocations)return[];$rawTotal='0.000000';foreach($allocations as $allocation)$rawTotal=$this->addDecimal($rawTotal,(string)$allocation['raw_amount']);$remainingMinor=$costMinor;$normalized=[];$last=count($allocations)-1;
        foreach($allocations as $index=>$allocation){$amountMinor=0;if($index===$last)$amountMinor=$remainingMinor;elseif($costMinor>0&&$this->compareDecimal($rawTotal,'0.000000')>0)$amountMinor=$this->proportionMinor($costMinor,(string)$allocation['raw_amount'],$rawTotal);$remainingMinor-=$amountMinor;$normalized[]=['valuation_layer_id'=>(int)$allocation['valuation_layer_id'],'quantity'=>(string)$allocation['quantity'],'cost_amount'=>$this->decimalFromMinor($amountMinor,$places)];}
        if($remainingMinor!==0)throw new InvalidArgumentException('Invoice stock cost allocations do not match the posted cost amount.');return$normalized;
    }
    private function customerReturnCandidates(array $invoiceLine,int $companyId,bool $lock=false):array
    {
        if(($invoiceLine['product_type']??'')!=='goods'||(int)($invoiceLine['sales_order_line_id']??0)<1)return[];
        $lockSql=$lock?' FOR UPDATE':'';
        if(($invoiceLine['cost_source']??null)==='stock_move'){
            $sql="SELECT ica.id AS invoice_cost_allocation_id,ica.quantity_product_uom AS invoice_cost_quantity,ica.cost_amount AS invoice_cost_amount,COALESCE((SELECT SUM(cra.quantity_product_uom) FROM customer_credit_note_return_allocations cra JOIN customer_invoice_lines cnl ON cnl.id=cra.credit_note_line_id JOIN customer_invoices cn ON cn.id=cnl.invoice_id WHERE cra.invoice_cost_allocation_id=ica.id AND cn.company_id=ica.company_id AND cn.document_type='credit_note' AND cn.state IN ('draft','posted')),0) AS allocated_invoice_quantity,COALESCE((SELECT SUM(cra.cost_amount) FROM customer_credit_note_return_allocations cra JOIN customer_invoice_lines cnl ON cnl.id=cra.credit_note_line_id JOIN customer_invoices cn ON cn.id=cnl.invoice_id WHERE cra.invoice_cost_allocation_id=ica.id AND cn.company_id=ica.company_id AND cn.document_type='credit_note' AND cn.state IN ('draft','posted')),0) AS allocated_invoice_cost,rl.id AS stock_move_line_id,retl.quantity_delta AS return_layer_quantity,retl.value_delta AS return_layer_value,retl.unit_cost AS return_layer_unit_cost,COALESCE((SELECT SUM(cra.quantity_product_uom) FROM customer_credit_note_return_allocations cra JOIN customer_invoice_lines cnl ON cnl.id=cra.credit_note_line_id JOIN customer_invoices cn ON cn.id=cnl.invoice_id WHERE cra.stock_move_line_id=rl.id AND cn.company_id=ica.company_id AND cn.document_type='credit_note' AND cn.state IN ('draft','posted')),0) AS allocated_return_quantity,COALESCE((SELECT SUM(cra.cost_amount) FROM customer_credit_note_return_allocations cra JOIN customer_invoice_lines cnl ON cnl.id=cra.credit_note_line_id JOIN customer_invoices cn ON cn.id=cnl.invoice_id WHERE cra.stock_move_line_id=rl.id AND cn.company_id=ica.company_id AND cn.document_type='credit_note' AND cn.state IN ('draft','posted')),0) AS allocated_return_cost,rm.id AS return_move_id,rm.reference AS return_reference,COALESCE(rl.lot_code_snapshot,lot.lot_code) AS lot_code FROM customer_invoice_stock_cost_allocations ica JOIN inventory_valuation_layers outbound ON outbound.id=ica.valuation_layer_id AND outbound.quantity_delta<0 JOIN stock_move_lines delivered_line ON delivered_line.id=outbound.stock_move_line_id JOIN stock_moves delivery ON delivery.id=delivered_line.move_id JOIN stock_move_lines rl ON rl.return_of_move_line_id=delivered_line.id JOIN stock_moves rm ON rm.id=rl.move_id AND rm.company_id=ica.company_id AND rm.return_of_move_id=delivery.id AND rm.state='done' JOIN inventory_valuation_layers retl ON retl.stock_move_line_id=rl.id AND retl.quantity_delta>0 LEFT JOIN stock_lots lot ON lot.id=rl.lot_id WHERE ica.company_id=:company AND ica.invoice_line_id=:invoice_line AND delivery.company_id=ica.company_id AND delivery.state='done' AND delivery.source_line_model='sales_order_line' AND delivery.source_line_id=:sales_line AND delivery.product_id=:product ORDER BY ica.id,rm.done_at,rm.id,rl.id".$lockSql;
            $query=$this->pdo->prepare($sql);$query->execute(['company'=>$companyId,'invoice_line'=>$invoiceLine['id'],'sales_line'=>$invoiceLine['sales_order_line_id'],'product'=>$invoiceLine['product_id']]);return$query->fetchAll();
        }
        $sql="SELECT NULL AS invoice_cost_allocation_id,'0.000000' AS invoice_cost_quantity,'0.000000' AS invoice_cost_amount,'0.000000' AS allocated_invoice_quantity,'0.000000' AS allocated_invoice_cost,rl.id AS stock_move_line_id,retl.quantity_delta AS return_layer_quantity,retl.value_delta AS return_layer_value,retl.unit_cost AS return_layer_unit_cost,COALESCE((SELECT SUM(cra.quantity_product_uom) FROM customer_credit_note_return_allocations cra JOIN customer_invoice_lines cnl ON cnl.id=cra.credit_note_line_id JOIN customer_invoices cn ON cn.id=cnl.invoice_id WHERE cra.stock_move_line_id=rl.id AND cn.company_id=rm.company_id AND cn.document_type='credit_note' AND cn.state IN ('draft','posted')),0) AS allocated_return_quantity,COALESCE((SELECT SUM(cra.cost_amount) FROM customer_credit_note_return_allocations cra JOIN customer_invoice_lines cnl ON cnl.id=cra.credit_note_line_id JOIN customer_invoices cn ON cn.id=cnl.invoice_id WHERE cra.stock_move_line_id=rl.id AND cn.company_id=rm.company_id AND cn.document_type='credit_note' AND cn.state IN ('draft','posted')),0) AS allocated_return_cost,rm.id AS return_move_id,rm.reference AS return_reference,COALESCE(rl.lot_code_snapshot,lot.lot_code) AS lot_code FROM stock_moves delivery JOIN stock_move_lines delivered_line ON delivered_line.move_id=delivery.id JOIN stock_move_lines rl ON rl.return_of_move_line_id=delivered_line.id JOIN stock_moves rm ON rm.id=rl.move_id AND rm.company_id=delivery.company_id AND rm.return_of_move_id=delivery.id AND rm.state='done' JOIN inventory_valuation_layers retl ON retl.stock_move_line_id=rl.id AND retl.quantity_delta>0 LEFT JOIN stock_lots lot ON lot.id=rl.lot_id WHERE delivery.company_id=:company AND delivery.state='done' AND delivery.source_line_model='sales_order_line' AND delivery.source_line_id=:sales_line AND delivery.product_id=:product ORDER BY rm.done_at,rm.id,rl.id".$lockSql;
        $query=$this->pdo->prepare($sql);$query->execute(['company'=>$companyId,'sales_line'=>$invoiceLine['sales_order_line_id'],'product'=>$invoiceLine['product_id']]);return$query->fetchAll();
