    private function availableReturnedProductQuantity(array $invoiceLine,int $companyId):string
    {
        $remainingByCost=[];$remainingByReturn=[];$available='0.000000';foreach($this->customerReturnCandidates($invoiceLine,$companyId) as $candidate){$returnId=(int)$candidate['stock_move_line_id'];$returnRemaining=$remainingByReturn[$returnId]??$this->maxZeroDecimal($this->subtractDecimal((string)$candidate['return_layer_quantity'],(string)$candidate['allocated_return_quantity']));$take=$returnRemaining;if($candidate['invoice_cost_allocation_id']!==null){$costId=(int)$candidate['invoice_cost_allocation_id'];$costRemaining=$remainingByCost[$costId]??$this->maxZeroDecimal($this->subtractDecimal((string)$candidate['invoice_cost_quantity'],(string)$candidate['allocated_invoice_quantity']));$take=$this->minDecimal($costRemaining,$returnRemaining);$remainingByCost[$costId]=$this->maxZeroDecimal($this->subtractDecimal($costRemaining,$take));}$remainingByReturn[$returnId]=$this->maxZeroDecimal($this->subtractDecimal($returnRemaining,$take));$available=$this->addDecimal($available,$take);}return$available;
    }
    private function allocateCustomerReturns(array $current,array $invoiceLine,int $creditNoteLineId,string $requestedProductQuantity,int $actorId):void
    {
        if($this->compareDecimal($requestedProductQuantity,'0.000000')<=0)return;$remaining=$requestedProductQuantity;$insert=$this->pdo->prepare('INSERT INTO customer_credit_note_return_allocations (company_id,credit_note_line_id,invoice_cost_allocation_id,stock_move_line_id,quantity_product_uom,cost_amount,created_by) VALUES (:company,:credit_line,:cost_allocation,:stock_line,:quantity,:cost,:actor)');$usedCost=[];$usedCostAmount=[];$usedReturn=[];$candidates=$this->customerReturnCandidates($invoiceLine,(int)$current['company_id'],true);
        foreach($candidates as $candidate){if($this->compareDecimal($remaining,'0.000000')<=0)break;$returnId=(int)$candidate['stock_move_line_id'];$returnRemaining=$this->maxZeroDecimal($this->subtractDecimal((string)$candidate['return_layer_quantity'],(string)$candidate['allocated_return_quantity']));if(isset($usedReturn[$returnId]))$returnRemaining=$this->maxZeroDecimal($this->subtractDecimal($returnRemaining,$usedReturn[$returnId]));$costId=$candidate['invoice_cost_allocation_id']===null?null:(int)$candidate['invoice_cost_allocation_id'];$costRemaining='999999999999.000000';if($costId!==null){$costRemaining=$this->maxZeroDecimal($this->subtractDecimal((string)$candidate['invoice_cost_quantity'],(string)$candidate['allocated_invoice_quantity']));if(isset($usedCost[$costId]))$costRemaining=$this->maxZeroDecimal($this->subtractDecimal($costRemaining,$usedCost[$costId]));}$take=$this->minDecimal($remaining,$this->minDecimal($returnRemaining,$costRemaining));if($this->compareDecimal($take,'0.000000')<=0)continue;
            $cost='0.000000';if($costId!==null){$costAmount=(string)$candidate['invoice_cost_amount'];$costRemainingAmount=$this->maxZeroDecimal($this->subtractDecimal($this->subtractDecimal($costAmount,(string)$candidate['allocated_invoice_cost']),$usedCostAmount[$costId]??'0.000000'));$cost=$this->compareDecimal($take,$costRemaining)===0?$costRemainingAmount:$this->calculate('CAST(ROUND(CAST(:amount AS DECIMAL(20,6))*CAST(:take AS DECIMAL(20,6))/NULLIF(CAST(:quantity AS DECIMAL(20,6)),0),6) AS DECIMAL(20,6))',['amount'=>$costRemainingAmount,'take'=>$take,'quantity'=>$costRemaining]);$cost=$this->maxZeroDecimal($cost);$usedCost[$costId]=$this->addDecimal($usedCost[$costId]??'0.000000',$take);$usedCostAmount[$costId]=$this->addDecimal($usedCostAmount[$costId]??'0.000000',$cost);}
            $insert->execute(['company'=>$current['company_id'],'credit_line'=>$creditNoteLineId,'cost_allocation'=>$costId,'stock_line'=>$returnId,'quantity'=>$take,'cost'=>$cost,'actor'=>$actorId]);$usedReturn[$returnId]=$this->addDecimal($usedReturn[$returnId]??'0.000000',$take);$remaining=$this->maxZeroDecimal($this->subtractDecimal($remaining,$take));
        }
        if($this->compareDecimal($remaining,'0.000000')>0)throw new InvalidArgumentException('Returned Quantity exceeds completed customer-return stock that is still available for this invoice line. Validate the Inventory return first; perpetual invoices also need their original stock-cost allocation.');
    }
    private function calculate(string $expression,array $parameters):string{$query=$this->pdo->prepare('SELECT '.$expression);$query->execute($parameters);return(string)$query->fetchColumn();}
    private function addDecimal(string $left,string $right):string{return$this->calculate('CAST(CAST(:left AS DECIMAL(20,6))+CAST(:right AS DECIMAL(20,6)) AS DECIMAL(20,6))',['left'=>$left,'right'=>$right]);}
    private function subtractDecimal(string $left,string $right):string{return$this->calculate('CAST(CAST(:left AS DECIMAL(20,6))-CAST(:right AS DECIMAL(20,6)) AS DECIMAL(20,6))',['left'=>$left,'right'=>$right]);}
    private function compareDecimal(string $left,string $right):int{return(int)$this->calculate('CASE WHEN CAST(:left AS DECIMAL(20,6))<CAST(:right AS DECIMAL(20,6)) THEN -1 WHEN CAST(:left_equal AS DECIMAL(20,6))=CAST(:right_equal AS DECIMAL(20,6)) THEN 0 ELSE 1 END',['left'=>$left,'right'=>$right,'left_equal'=>$left,'right_equal'=>$right]);}
    private function minDecimal(string $left,string $right):string{return$this->calculate('CAST(CASE WHEN CAST(:left AS DECIMAL(20,6))<=CAST(:right AS DECIMAL(20,6)) THEN CAST(:left_value AS DECIMAL(20,6)) ELSE CAST(:right_value AS DECIMAL(20,6)) END AS DECIMAL(20,6))',['left'=>$left,'right'=>$right,'left_value'=>$left,'right_value'=>$right]);}
    private function maxZeroDecimal(string $value):string{return$this->calculate('CAST(CASE WHEN CAST(:value AS DECIMAL(20,6))>0 THEN CAST(:value_copy AS DECIMAL(20,6)) ELSE 0 END AS DECIMAL(20,6))',['value'=>$value,'value_copy'=>$value]);}
    private function proportionMinor(int $amountMinor,string $quantity,string $orderedQuantity):int
    {
        if($this->compareDecimal($orderedQuantity,'0.000000')<=0)throw new InvalidArgumentException('A Sales Order line must have a positive ordered quantity before it can be invoiced.');
        return(int)$this->calculate('CAST(ROUND(CAST(:amount AS DECIMAL(20,0))*CAST(:quantity AS DECIMAL(20,6))/NULLIF(CAST(:ordered AS DECIMAL(20,6)),0),0) AS DECIMAL(20,0))',['amount'=>(string)$amountMinor,'quantity'=>$quantity,'ordered'=>$orderedQuantity]);
    }
    private function decimalEquals(string $left,string $right):bool{return(bool)$this->calculate('CAST(CAST(:left AS DECIMAL(20,6))=CAST(:right AS DECIMAL(20,6)) AS UNSIGNED)',['left'=>$left,'right'=>$right]);}
    private function nextInvoiceNumber(int $companyId,int $year): string
    {
        $this->pdo->prepare('INSERT INTO customer_invoice_sequences (company_id,sequence_year,last_number) VALUES (:company,:year,0) ON DUPLICATE KEY UPDATE company_id=VALUES(company_id)')->execute(['company'=>$companyId,'year'=>$year]);
        $query=$this->pdo->prepare('SELECT last_number FROM customer_invoice_sequences WHERE company_id=:company AND sequence_year=:year FOR UPDATE');$query->execute(['company'=>$companyId,'year'=>$year]);$next=(int)$query->fetchColumn()+1;
        $this->pdo->prepare('UPDATE customer_invoice_sequences SET last_number=:number WHERE company_id=:company AND sequence_year=:year')->execute(['number'=>$next,'company'=>$companyId,'year'=>$year]);return sprintf($this->documentPrefix($companyId,'customer_invoice','INV').'%04d-%05d',$year,$next);
    }

