    private function company(UserContext $user,Authorization $authorization,mixed $raw): int
    {
        $id=$raw===null||$raw===''?($user->defaultCompanyId??(count($user->companyIds)===1?$user->companyIds[0]:null)):$this->positiveId($raw,'Company');if(!$id||!$authorization->canAccessCompany($id))throw new InvalidArgumentException('Select an allowed company.');return $id;
    }
    private function positiveId(mixed $value,string $label):int{$id=filter_var($value,FILTER_VALIDATE_INT);if($id===false||$id<1)throw new InvalidArgumentException($label.' must be a positive integer.');return $id;}
    private function invoiceDecimal(mixed $value,string $label,int $scale):string{$raw=trim((string)($value??''));if(!in_array($scale,[4,6],true)||!preg_match('/^(?:0|[1-9][0-9]{0,11})(?:\\.[0-9]{1,'.$scale.'})?$/D',$raw))throw new InvalidArgumentException($label.' must be a nonnegative decimal with no more than '.$scale.' decimal places.');return$raw;}
    private function date(mixed $value,string $label):string{$raw=trim((string)($value??''));$parsed=\DateTimeImmutable::createFromFormat('!Y-m-d',$raw);if(!$parsed||$parsed->format('Y-m-d')!==$raw)throw new InvalidArgumentException($label.' must be a valid date in YYYY-MM-DD format.');return $raw;}
    private function boolean(mixed $value,string $label):bool{if(!is_bool($value)&&!in_array($value,[0,1,'0','1','true','false'],true))throw new InvalidArgumentException($label.' must be true or false.');$parsed=filter_var($value,FILTER_VALIDATE_BOOLEAN,FILTER_NULL_ON_FAILURE);if($parsed===null)throw new InvalidArgumentException($label.' must be true or false.');return $parsed;}
    private function minor(string $amount,int $places):int
    {
        if(!preg_match('/^(0|[1-9][0-9]{0,11})(?:\.([0-9]{1,6}))?$/D',$amount,$m))throw new InvalidArgumentException('Invoice amounts must be nonnegative and below 1 trillion in the company currency.');
        $factor=10**$places;$fraction=str_pad($m[2]??'', $places+1,'0');$minor=(int)$m[1]*$factor+(int)substr($fraction,0,$places);if((int)($fraction[$places]??'0')>=5)$minor++;return $minor;
    }
    private function decimalFromMinor(int $amount,int $places):string{$factor=10**$places;$whole=intdiv($amount,$factor);if($places===0)return(string)$whole;return$whole.'.'.str_pad((string)($amount%$factor),$places,'0',STR_PAD_LEFT);}
    private function audit(int $companyId,int $actorId,int $recordId,string $model,string $event,?array $old,array $new,string $remoteAddress):void
