        $query->bindValue(':company',$companyId,PDO::PARAM_INT);$query->bindValue(':user',$actorId,PDO::PARAM_INT);$query->bindValue(':event',$event);$query->bindValue(':model',$model);$query->bindValue(':record',$recordId,PDO::PARAM_INT);$query->bindValue(':old_values',$old===null?null:json_encode($old,JSON_THROW_ON_ERROR),$old===null?PDO::PARAM_NULL:PDO::PARAM_STR);$query->bindValue(':new_values',json_encode($new,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$query->bindValue(':ip',$ip,$ip===null?PDO::PARAM_NULL:PDO::PARAM_LOB);$query->execute();
